export type VocabularyCoverTheme =
  | "oxford"
  | "botanical"
  | "harbor"
  | "sunset"
  | "ink";

export type VocabularyMastery = "new" | "learning" | "review" | "mastered";
export type ReviewMode = "flashcard" | "spelling";
export type ReviewDirection = "english-chinese" | "chinese-english";
export type ReviewRating = "again" | "hard" | "good" | "easy";

export interface VocabularyBook {
  id: string;
  name: string;
  subtitle: string;
  description: string;
  theme: VocabularyCoverTheme;
  accent: string;
  createdAt: string;
  updatedAt: string;
}

/** 用户自己创建的分章：批量导入成书时建立，名字由用户起。 */
export interface VocabularyChapter {
  id: string;
  name: string;
  createdAt: string;
  /** 这一章立在哪本单词本里。旧数据没有，按空章处理即可。 */
  wordbookId?: string;
}

export interface VocabularyWord {
  id: string;
  term: string;
  lemma: string;
  pronunciation?: string;
  partOfSpeech?: string;
  cefr?: string;
  meaningsZh: string[];
  definitionEn: string;
  collocations: string[];
  examples: LanguageInsight["examples"];
  usageNotes: string[];
  sourceLabel: string;
  sourceExcerpt?: string;
  categoryId?: string;
  bookId?: string;
  moduleId?: string;
  nodeId?: string;
  /** 这个词属于哪一本单词本（VocabularyBook.id）。旧数据没有，水合时补上。 */
  wordbookId?: string;
  /** 批量导入归入的用户分章（VocabularyChapter.id）。 */
  chapterId?: string;
  addedAt: string;
  reviewStage: number;
  reviewCount: number;
  correctStreak: number;
  lapses: number;
  nextReviewAt: string;
  lastReviewedAt?: string;
  mastery: VocabularyMastery;
}

/**
 * 一场卡片记忆。规则很直白：
 *   记住了 +1、很轻松 +2（一次就过）、模糊原地不动（还得再见一面）、没记住清零；
 *   一个词连着答对 2 次就从队列里清出去，没答对的塞回后面的随机位置，
 *   什么时候再见没有准数 —— 所以「这一场什么时候结束」由队列自己说了算。
 */
export interface ReviewSession {
  /** 还没过的词：出题顺序就是这里的顺序。 */
  wordIds: string[];
  /** 出到第几个。 */
  index: number;
  /** 每个词已经连着答对几次。 */
  streak: Record<string, number>;
  /** 这一场每个词答过什么（收尾统计用）。 */
  ratings: Record<string, ReviewRating[]>;
  /** 这一场一共出过多少张牌。 */
  attempts: number;
  completed: boolean;
}

interface PersistedVocabulary {
  /** v1 的单本字段：老数据还有它，水合时并进 books。 */
  book?: VocabularyBook;
  /** v2：多本单词本并排。 */
  books?: VocabularyBook[];
  activeBookId?: string;
  words: VocabularyWord[];
  /** 旧数据没有这一项，水合时按空数组补齐。 */
  chapters?: VocabularyChapter[];
}

export interface ImportChapterResult {
  chapterId: string;
  added: number;
  skipped: number;
}

interface VocabularyState {
  initialized: boolean;
  /** 现在这一份数据属于谁：null = 没登录时的本机存档；否则是账号 id。 */
  ownerId: string | null;
  /** 当前翻开的这一本（books 里 activeBookId 指向的那本）。 */
  book: VocabularyBook;
  /** 全部单词本：默认一本，用户可以再新建，各自装各自的词。 */
  books: VocabularyBook[];
  activeBookId: string;
  /** 所有本书的词都在这里，按 wordbookId 归属；页面自己按当前这本过滤。 */
  words: VocabularyWord[];
  /** 用户自己创建的分章（批量导入成书时建立）。 */
  chapters: VocabularyChapter[];
  reviewMode: ReviewMode;
  reviewDirection: ReviewDirection;
  session: ReviewSession | null;
  hydrate: () => Promise<void>;
  /** 新建一本空的单词本，并翻到它。 */
  createBook: (name: string, theme?: VocabularyCoverTheme) => VocabularyBook;
  /** 换一本翻。 */
  setActiveBook: (id: string) => void;
  /** 改书名 / 封面，作用在当前这一本上。 */
  renameBook: (id: string, name: string) => void;
  updateBook: (
    patch: Partial<
      Pick<
        VocabularyBook,
        "name" | "subtitle" | "description" | "theme" | "accent"
      >
    >,
  ) => void;
  addInsight: (
    insight: LanguageInsight,
    sourceLabel?: string,
    sourceExcerpt?: string,
    metadata?: Pick<
      VocabularyWord,
      "categoryId" | "bookId" | "moduleId" | "nodeId" | "chapterId" | "chapterId"
    >,
  ) => void;
  addManyInsights: (
    insights: LanguageInsight[],
    sourceLabel?: string,
    sourceExcerpt?: string,
    metadata?: Pick<
      VocabularyWord,
      "categoryId" | "bookId" | "moduleId" | "nodeId" | "chapterId" | "chapterId"
    >,
  ) => number;
  /**
   * 批量导入成章：建立用户命名的分章，把词条逐一落成卡片归入该章。
   * 与全书既有词条重复（忽略大小写）的一律跳过，返回值里如实交代。
   */
  importChapter: (
    name: string,
    entries: Array<{ term: string; insight: LanguageInsight }>,
    sourceLabel?: string,
  ) => ImportChapterResult;
  addCorpusEntry: (entry: CorpusEntry) => void;
  removeWord: (id: string) => void;
  /** 改一个词的字段（词头、音标、词性、释义……）。 */
  updateWord: (
    id: string,
    patch: Partial<
      Pick<
        VocabularyWord,
        | "term"
        | "lemma"
        | "pronunciation"
        | "partOfSpeech"
        | "cefr"
        | "meaningsZh"
        | "definitionEn"
        | "collocations"
        | "usageNotes"
        | "examples"
      >
    >,
  ) => void;
  /** 一次删一批词：单删和目录里的多选都走它。 */
  removeWords: (ids: string[]) => void;
  /** 把一批词搬去另一本单词本；目标里已有同一个词的跳过，如实报数。 */
  moveWords: (
    ids: string[],
    wordbookId: string,
  ) => { moved: number; skipped: number };
  /** 删掉一本单词本，连同它名下的词和分章。最后一本不给删，返回是否真删了。 */
  deleteBook: (id: string) => boolean;
  setReviewMode: (mode: ReviewMode) => void;
  setReviewDirection: (direction: ReviewDirection) => void;
  startReview: () => void;
  startReviewWithIds: (ids: string[]) => void;
  gradeCurrentWord: (rating: ReviewRating) => void;
  /** 放大卡片里的翻页：只挪光标、不计分，翻过去看一眼就走。 */
  stepSession: (delta: number) => void;
  closeReview: () => void;
}

