/** 词条算哪一本的：旧数据没写 wordbookId 的一律算第一本。 */
export function wordbookIdOf(word: VocabularyWord) {
  return word.wordbookId ?? DEFAULT_VOCABULARY_BOOK.id;
}

function masteryFor(stage: number, reviewCount: number): VocabularyMastery {
  if (reviewCount === 0) return "new";
  if (stage >= 5 && reviewCount >= 6) return "mastered";
  if (reviewCount >= 2) return "review";
  return "learning";
}

function normalizeTerm(term: string) {
  return term.trim().toLowerCase().replace(/\s+/g, " ");
}

function nextDateForStage(stage: number) {
  const days =
    REVIEW_INTERVALS_DAYS[Math.min(stage, REVIEW_INTERVALS_DAYS.length - 1)] ??
    30;
  return relativeDate(Math.max(0, days), 9);
}

function insightToWord(
  insight: LanguageInsight,
  sourceLabel: string,
  sourceExcerpt?: string,
  metadata?: Pick<
    VocabularyWord,
    "categoryId" | "bookId" | "moduleId" | "nodeId" | "chapterId"
  >,
  wordbookId: string = DEFAULT_VOCABULARY_BOOK.id,
): VocabularyWord {
  return {
    id: `word-${createId()}`,
    // 词归哪一本单词本，落库时就写死 —— 之后换不换当前这本都不影响它。
    wordbookId,
    term: insight.term,
    lemma: insight.lemma || insight.term,
    pronunciation: insight.pronunciation,
    partOfSpeech: insight.partOfSpeech,
    cefr: insight.cefr,
    meaningsZh: insight.meaningsZh,
    definitionEn: insight.definitionEn,
    collocations: insight.collocations,
    examples: insight.examples,
    usageNotes: insight.usageNotes,
    sourceLabel,
    sourceExcerpt,
    ...metadata,
    addedAt: new Date().toISOString(),
    reviewStage: 0,
    reviewCount: 0,
    correctStreak: 0,
    lapses: 0,
    nextReviewAt: new Date().toISOString(),
    mastery: "new",
  };
}

async function persist(
  ownerId: string | null,
  books: VocabularyBook[],
  activeBookId: string,
  words: VocabularyWord[],
  chapters: VocabularyChapter[],
) {
  if (typeof indexedDB === "undefined") return;
  await idbSet(scopedLocalKey(STORAGE_KEY, ownerId), {
    books,
    activeBookId,
    words,
    chapters,
  }).catch(() => undefined);
}

/** 把当前这一份状态原样落盘 —— 每次改完都调它，不用再逐个字段传。 */
function persistState(get: () => VocabularyState) {
  const state = get();
  void persist(
    state.ownerId,
    state.books,
    state.activeBookId,
    state.words,
    state.chapters,
  );
}

/** 现在登录的是谁。登录后存档写进「键::账号 id」，各账号互不串门。 */
function currentOwnerId(): string | null {
  return useAccountStore.getState().session?.user.id ?? null;
}

/** 第几次水合：账号切得快时，先出发的那次回来就作废，别拿旧桶盖新桶。 */
let hydrateTicket = 0;

function applyRating(
  word: VocabularyWord,
  rating: ReviewRating,
): VocabularyWord {
  const now = new Date().toISOString();
  let stage = word.reviewStage;
  let reviewCount = word.reviewCount + 1;
  let correctStreak = word.correctStreak;
  let lapses = word.lapses;

  if (rating === "again") {
    stage = Math.max(0, stage - 2);
    correctStreak = 0;
    lapses += 1;
  } else if (rating === "hard") {
    stage = Math.max(0, stage);
    correctStreak = Math.max(0, correctStreak - 1);
  } else if (rating === "good") {
    stage = Math.min(REVIEW_INTERVALS_DAYS.length - 1, stage + 1);
    correctStreak += 1;
  } else {
    stage = Math.min(REVIEW_INTERVALS_DAYS.length - 1, stage + 2);
    correctStreak += 1;
  }

  // Leafia requires at least two meaningful interactions before a word can
  // graduate into a longer interval.
  if (reviewCount < 2) {
    stage = Math.min(stage, 1);
  }

  return {
    ...word,
    reviewStage: stage,
    reviewCount,
    correctStreak,
    lapses,
    lastReviewedAt: now,
    nextReviewAt:
      rating === "again"
        ? relativeDate(0, new Date().getHours() + 1)
        : nextDateForStage(stage),
    mastery: masteryFor(stage, reviewCount),
  };
}

/**
 * 2026-10-13 之前，全新的浏览器第一次打开会被种上 10 个示例词；
 * 现在新用户是干干净净的一本空单词本。老设备里还躺着那批示例词的，
 * 水合时按「词 + 来源 + 音标」的完整签名清出去 —— 用户自己收的词
 * 签名对不上，一个都不动。
 */
function seedKeyOf(
  word: Pick<VocabularyWord, "term" | "sourceLabel" | "pronunciation">,
) {
  return `${normalizeTerm(word.term)}|${word.sourceLabel}|${word.pronunciation ?? ""}`;
}

const LEGACY_SEED_KEYS = new Set(createSeedWords().map(seedKeyOf));

export const useVocabulary = create<VocabularyState>((set, get) => ({
  initialized: false,
  ownerId: currentOwnerId(),
  book: DEFAULT_VOCABULARY_BOOK,
  books: [DEFAULT_VOCABULARY_BOOK],
  activeBookId: DEFAULT_VOCABULARY_BOOK.id,
  words: [],
  chapters: [],
  reviewMode: "flashcard",
  reviewDirection: "english-chinese",
  session: null,

  async hydrate() {
    const ownerId = currentOwnerId();
    if (get().initialized && get().ownerId === ownerId) return;
    const ticket = ++hydrateTicket;
    // 没登录时照旧走旧品牌回落（老设备那份数据在裸键上）；账号的桶是
    // 新开的，直接读，不用再翻 inkflow 前缀。
    const stored = ownerId
      ? await idbGet<PersistedVocabulary>(
          scopedLocalKey(STORAGE_KEY, ownerId),
        ).catch(() => undefined)
      : await idbGetWithLegacyFallback<PersistedVocabulary>(STORAGE_KEY);
    if (ticket !== hydrateTicket) return;
    if (stored && Array.isArray(stored.words)) {
      // v1 只存了一本（stored.book）；v2 存的是 books + activeBookId。
      // 两代都读得进来：老数据那本就当第一本，没归属的词全并进它名下。
      const source =
        stored.books && stored.books.length > 0
          ? stored.books
          : stored.book
            ? [stored.book]
            : [DEFAULT_VOCABULARY_BOOK];
      const books = source.map((entry) => {
        const merged = { ...DEFAULT_VOCABULARY_BOOK, ...entry };
        // 旧名字里带着词典品牌，顺手收拾掉。
        if (merged.name === "我的牛津词汇书") {
          merged.name = DEFAULT_VOCABULARY_BOOK.name;
        }
        return merged;
      });
      const activeBookId =
        books.find((entry) => entry.id === stored.activeBookId)?.id ??
        books[0]!.id;
      const legacyBookId = stored.books?.length ? null : books[0]!.id;
      const words = stored.words
        .filter((word) => !LEGACY_SEED_KEYS.has(seedKeyOf(word)))
        .map((word) =>
          word.wordbookId
            ? word
            : { ...word, wordbookId: legacyBookId ?? activeBookId },
        );
      set({
        books,
        activeBookId,
        book: books.find((entry) => entry.id === activeBookId) ?? books[0]!,
        words,
        chapters: stored.chapters ?? [],
        ownerId,
        initialized: true,
      });
      return;
    }
    const book = {
      ...DEFAULT_VOCABULARY_BOOK,
      updatedAt: new Date().toISOString(),
    };
    // 全新用户（或新账号）就一本空单词本：一个词都不预置。
    set({
      books: [book],
      activeBookId: book.id,
      book,
      words: [],
      chapters: [],
      ownerId,
      initialized: true,
    });
    persistState(get);
  },

  createBook(name, theme = "botanical") {
    const now = new Date().toISOString();
    const palette =
      COVER_THEMES.find((entry) => entry.id === theme) ?? COVER_THEMES[0]!;
    const book: VocabularyBook = {
      id: `wordbook-${createId()}`,
      name: name.trim() || "新的单词本",
      subtitle: "Leafia · Wordbook",
      description: "自己新建的单词本，词条由你一条条收进来。",
      theme: palette.id,
      accent: palette.accent,
      createdAt: now,
      updatedAt: now,
    };
    set({
      books: [...get().books, book],
      activeBookId: book.id,
      book,
      session: null,
    });
    persistState(get);
    return book;
  },

  setActiveBook(id) {
    const book = get().books.find((entry) => entry.id === id);
    if (!book) return;
    // 换一本只是换「翻开的这一本」：分章是全部分章（各自带 wordbookId），
    // 不能在这儿清掉，否则一换本、别的本的分章就跟着没了。
    set({ activeBookId: id, book, session: null });
    persistState(get);
  },

  renameBook(id, name) {
    const trimmed = name.trim();
    if (!trimmed) return;
    const books = get().books.map((entry) =>
      entry.id === id
        ? { ...entry, name: trimmed, updatedAt: new Date().toISOString() }
        : entry,
    );
    set({
      books,
      book:
        books.find((entry) => entry.id === get().activeBookId) ?? get().book,
    });
    persistState(get);
  },

  updateBook(patch) {
    const now = new Date().toISOString();
    const activeBookId = get().activeBookId;
    const books = get().books.map((entry) =>
      entry.id === activeBookId ? { ...entry, ...patch, updatedAt: now } : entry,
    );
    set({
      books,
      book:
        books.find((entry) => entry.id === activeBookId) ?? get().book,
    });
    persistState(get);
  },

  addInsight(
    insight,
    sourceLabel = "词典",
    sourceExcerpt,
    metadata,
  ) {
    const normalized = normalizeTerm(insight.term);
    if (!normalized) return;
    const wordbookId = get().activeBookId;
    // 「已经有了」是就当前这一本说的：另一本里的同一个词不妨碍这本再收一次。
    const existing = get().words.find(
      (word) =>
        wordbookIdOf(word) === wordbookId &&
        normalizeTerm(word.term) === normalized,
    );
    if (existing) {
      const words = get().words.map((word) =>
        word.id === existing.id
          ? {
              ...word,
              meaningsZh: insight.meaningsZh,
              definitionEn: insight.definitionEn,
              collocations: insight.collocations,
              examples: insight.examples,
              usageNotes: insight.usageNotes,
              ...metadata,
            }
          : word,
      );
      set({ words });
      persistState(get);
      return;
    }

    const words = [
      insightToWord(insight, sourceLabel, sourceExcerpt, metadata, wordbookId),
      ...get().words,
    ];
    set({ words });
    persistState(get);
  },

  addManyInsights(
    insights,
    sourceLabel = "Imported document",
    sourceExcerpt,
    metadata,
  ) {
    const wordbookId = get().activeBookId;
    // 查重也只查当前这本：另一本里收过的词，这本照样能收。
    const existing = new Set(
      get()
        .words.filter((word) => wordbookIdOf(word) === wordbookId)
        .map((word) => normalizeTerm(word.term)),
    );
    const additions: VocabularyWord[] = [];
    for (const insight of insights) {
      const normalized = normalizeTerm(insight.term);
      if (!normalized || existing.has(normalized)) continue;
      existing.add(normalized);
      additions.push(
        insightToWord(
          insight,
          sourceLabel,
          sourceExcerpt,
          metadata,
          wordbookId,
        ),
      );
    }
    if (additions.length === 0) return 0;
    const words = [...additions, ...get().words];
    set({ words });
    persistState(get);
    return additions.length;
  },

  importChapter(name, entries, sourceLabel = "批量导入") {
    const chapterId = `chapter-${createId()}`;
    const wordbookId = get().activeBookId;
    const existing = new Set(
      get()
        .words.filter((word) => wordbookIdOf(word) === wordbookId)
        .map((word) => normalizeTerm(word.term)),
    );
    const additions: VocabularyWord[] = [];
    for (const entry of entries) {
      const normalized = normalizeTerm(entry.term);
      if (!normalized || existing.has(normalized)) continue;
      existing.add(normalized);
      additions.push(
        insightToWord(entry.insight, sourceLabel, undefined, { chapterId }, wordbookId),
      );
    }
    // 一个词都没进来就不立这一章 —— 返回空 chapterId，界面据此如实提示。
    if (additions.length === 0) {
      return { chapterId: "", added: 0, skipped: entries.length };
    }
    const chapter: VocabularyChapter = {
      id: chapterId,
      name: name.trim() || "未命名词单",
      createdAt: new Date().toISOString(),
      wordbookId,
    };
    const chapters = [...get().chapters, chapter];
    const words = [...additions, ...get().words];
    set({ chapters, words });
    persistState(get);
    return {
      chapterId,
      added: additions.length,
      skipped: entries.length - additions.length,
    };
  },

  addCorpusEntry(entry) {
    get().addInsight(
      {
        term: entry.term,
        lemma: entry.normalizedTerm,
        meaningsZh: entry.meaningsZh,
        definitionEn: entry.definitionEn,
        collocations: entry.collocations,
        examples: [],
        usageNotes: [],
        provider: "mock",
      },
      entry.sourceLabel,
    );
  },

  removeWord(id) {
    get().removeWords([id]);
  },

  updateWord(id, patch) {
    const words = get().words.map((word) => {
      if (word.id !== id) return word;
      const merged = { ...word, ...patch };
      // 改了词头，lemma 跟着走（lemma 本来就是「这个词的词典形」）。
      if (patch.term !== undefined && patch.lemma === undefined) {
        merged.lemma = patch.term;
      }
      return merged;
    });
    set({ words });
    persistState(get);
  },

  removeWords(ids) {
    if (ids.length === 0) return;
    const doomed = new Set(ids);
    const words = get().words.filter((word) => !doomed.has(word.id));
    set({ words });
    persistState(get);
  },

  moveWords(ids, wordbookId) {
    const target = get().books.find((entry) => entry.id === wordbookId);
    if (!target || ids.length === 0) return { moved: 0, skipped: 0 };
    const moving = new Set(ids);
    const taken = new Set(
      get()
        .words.filter((word) => wordbookIdOf(word) === wordbookId)
        .map((word) => normalizeTerm(word.term)),
    );
    let moved = 0;
    let skipped = 0;
    const words = get().words.map((word) => {
      if (!moving.has(word.id)) return word;
      const key = normalizeTerm(word.term);
      // 目标本里已经有同一个词：不动它，也不搬出重复的一条。
      if (taken.has(key)) {
        skipped += 1;
        return word;
      }
      taken.add(key);
      moved += 1;
      // 分章是原来那本里的，一搬过去就对不上了，一并清掉。
      return { ...word, wordbookId, chapterId: undefined };
    });
    if (moved > 0) {
      set({ words });
      persistState(get);
    }
    return { moved, skipped };
  },

  deleteBook(id) {
    const { books } = get();
    // 最后一本不给删：删光了连「收词」都没地方放。
    if (books.length <= 1 || !books.some((entry) => entry.id === id)) {
      return false;
    }
    const remaining = books.filter((entry) => entry.id !== id);
    const words = get().words.filter((word) => wordbookIdOf(word) !== id);
    const chapters = get().chapters.filter(
      (chapter) => (chapter.wordbookId ?? "") !== id,
    );
    const activeBookId =
      get().activeBookId === id ? remaining[0]!.id : get().activeBookId;
    set({
      books: remaining,
      words,
      chapters,
      activeBookId,
      book:
        remaining.find((entry) => entry.id === activeBookId) ?? remaining[0]!,
      session: null,
    });
    persistState(get);
    return true;
  },

  setReviewMode(mode) {
    set({ reviewMode: mode });
  },

  setReviewDirection(direction) {
    set({ reviewDirection: direction });
  },

  startReview() {
    const now = Date.now();
    // 复习的是当前翻开的这一本：换一本就是另一套词、另一条进度。
    const pool = get().words.filter(
      (word) => wordbookIdOf(word) === get().activeBookId,
    );
    const due = pool.filter(
      (word) => new Date(word.nextReviewAt).getTime() <= now,
    );
    const queue = (due.length > 0 ? due : pool).slice(0, 12);
    if (queue.length === 0) return;
    set({
      session: {
        wordIds: queue.map((word) => word.id),
        index: 0,
        streak: {},
        ratings: {},
        attempts: 0,
        completed: false,
      },
    });
  },

  startReviewWithIds(ids) {
    const known = new Set(get().words.map((word) => word.id));
    const queue = [...new Set(ids)].filter((id) => known.has(id));
    if (queue.length === 0) return;
    set({
      session: {
        wordIds: queue,
        index: 0,
        streak: {},
        ratings: {},
        attempts: 0,
        completed: false,
      },
    });
  },

  gradeCurrentWord(rating) {
    const session = get().session;
    if (!session || session.completed) return;
    const wordId = session.wordIds[session.index];
    if (!wordId) return;

    // 记住了 +1；很轻松 +2（一次就过）；模糊留在原地（这一面还得再见）；
    // 没记住清零。连着攒够两次，这个词就算过了。
    const step = rating === "easy" ? 2 : rating === "good" ? 1 : 0;
    const streak =
      rating === "again" ? 0 : (session.streak[wordId] ?? 0) + step;
    const cleared = streak >= 2;

    // 过了的和没记住的都落进复习进度；「模糊」先不动它，等下一个答案。
    const shouldPersistRating = cleared || rating === "again";
    const words = shouldPersistRating
      ? get().words.map((word) =>
          word.id === wordId ? applyRating(word, rating) : word,
        )
      : get().words;

    const queue = [...session.wordIds];
    queue.splice(session.index, 1);
    if (!cleared) {
      // 没过：塞回后面某个随机位置 —— 下次什么时候再见，没个准数。
      const span = queue.length - session.index + 1;
      const at = Math.min(
        session.index + Math.floor(Math.random() * span),
        queue.length,
      );
      queue.splice(at, 0, wordId);
    }

    const nextSession: ReviewSession = {
      ...session,
      wordIds: queue,
      // 光标不动：抽掉当前这张之后，它指着的正好是下一张。
      streak: { ...session.streak, [wordId]: streak },
      ratings: {
        ...session.ratings,
        [wordId]: [...(session.ratings[wordId] ?? []), rating],
      },
      attempts: session.attempts + 1,
      completed: queue.length === 0,
    };

    set({ words, session: nextSession });
    persistState(get);
  },

  stepSession(delta) {
    const session = get().session;
    if (!session || session.completed) return;
    const count = session.wordIds.length;
    if (count === 0) return;
    // 到头绕回去：放大卡片是拿来一叠翻着看的，翻不过去比绕回去更别扭。
    const index = (session.index + delta + count) % count;
    if (index === session.index) return;
    set({ session: { ...session, index } });
  },

  closeReview() {
    set({ session: null });
  },
}));

// 登录、退出、换账号：换一份存档 —— 新注册的账号从一本空单词本开始，
// 退出后回到没登录时那份本机数据。
useAccountStore.subscribe((state, previous) => {
  const next = state.session?.user.id ?? null;
  const before = previous.session?.user.id ?? null;
  if (next === before) return;
  void useVocabulary.getState().hydrate();
});

export function dueVocabularyWords(words: VocabularyWord[], now = Date.now()) {
  return words.filter((word) => new Date(word.nextReviewAt).getTime() <= now);
}

export function vocabularyMasteryCounts(words: VocabularyWord[]) {
  return {
    new: words.filter((word) => word.mastery === "new").length,
    learning: words.filter((word) => word.mastery === "learning").length,
    review: words.filter((word) => word.mastery === "review").length,
    mastered: words.filter((word) => word.mastery === "mastered").length,
  };
}

export function stageLabel(word: VocabularyWord) {
  if (word.mastery === "new") return "尚未开始";
  return `第 ${Math.min(word.reviewStage + 1, REVIEW_INTERVALS_DAYS.length)}/${REVIEW_INTERVALS_DAYS.length} 轮`;
}
